original_comparison_table = rv.comparison_table


def completed_comparison(doc):
    original_comparison_table(doc)
    rv.base.rich(doc,
        'Сопоставление трёх адаптивных вариантов позволяет оценить влияние передачи параметрических оценок в регулятор при одинаковой настройке наблюдателя. По сравнению с адаптацией только наблюдателя взвешенное обновление снижает средний максимум тока на 24,8 и 27,1%, но увеличивает MAE на 76,5 и 58,6%, а энергию потерь — на 8,3 и 8,1%. Снижение максимума тока не гарантирует уменьшения энергии потерь, определяемой интегралом R<sub>s</sub>(t)|i<sub>s</sub>(t)|² по всему интервалу. Верхние границы дополнительных 95%-ных интервалов отношений токовых максимумов равны 0,800 и 0,771; нижние границы отношений MAE — 1,257 и 1,196. Следовательно, в рассматриваемых условиях уменьшение максимального тока при передаче оценок сопровождается ухудшением точности относительно варианта с адаптацией только наблюдателя.')
    rv.base.rich(doc,
        'В основной серии базовый наблюдатель имеет иное q<sub>M</sub>, поэтому отдельно проведено сравнение при одинаковом q<sub>M</sub> = 0,01. Результаты приведены в таблице 3. В каждом режиме сопоставлены те же 20 реализаций, что исключает изменение набора внешних воздействий между вариантами.')
    rows = [['Режим', 'MAE базовой\nсистемы, рад/с', 'MAE при взвешенном\nобновлении, рад/с', 'Отношение MAE\nи 95%-ный интервал']]
    for case, label in [('parameter_drift', 'Изменение параметров'), ('composite', 'Совместные возмущения')]:
        a = analysis[case]
        x = a['confidence_feedback']['tracking_mae_rad_s']
        fmt = lambda value: f'{value:.3f}'.replace('.', ',')
        rows.append([label, fmt(a['fixed_same_q']['tracking_mae_rad_s']), fmt(x['mean']),
                     f"{fmt(x['ratio_to_fixed_same_q'])} [{fmt(x['ratio_ci95'][0])}; {fmt(x['ratio_ci95'][1])}]"])
    rv.plain_table(doc, 'Таблица 3 – Дополнительное сравнение при одинаковом qM = 0,01', [3.8, 3.7, 4.1, 4.3], rows)
    (HERE / 'completion_control_table.json').write_text(json.dumps(rows, ensure_ascii=False, indent=2), encoding='utf-8')
    rv.base.rich(doc,
        'При одинаковом q<sub>M</sub> преимущество адаптивной системы по погрешности скорости сохраняется. Простое увеличение q<sub>M</sub> базового наблюдателя до значения адаптивного не воспроизводит полученное улучшение. Следовательно, различие настройки модели нагрузки не является достаточным объяснением выигрыша основной серии. Контроль выполнен при одном общем значении q<sub>M</sub> и не заменяет исследования чувствительности во всём диапазоне настроек.')


rv.comparison_table = completed_comparison

